'use client'

import { useRef } from 'react'
import { focusElement, useEffectPropSignal, useId, useSignalEffect } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import styles from './alert-dialog.module.css'

export interface AlertDialogLabels {
  confirm?: string
  cancel?: string
}

export interface AlertDialogProps {
  open: boolean
  title: string
  description: string
  onConfirm: () => void
  onCancel: () => void
  labels?: AlertDialogLabels
  /**
   * `destructive` styles the confirm button as a danger action; `default` styles it as the
   * primary action. Use `destructive` for anything that deletes.
   *
   * @defaultValue `default`
   * @see the component manifest
   */
  variant?: 'destructive' | 'default'
}

export function AlertDialog({
  open,
  title,
  description,
  onConfirm,
  onCancel,
  labels,
  variant = 'default',
}: AlertDialogProps) {
  const dialogRef = useRef<HTMLDivElement>(null)
  const titleId = useId('cascivo-alert-dialog-title')
  const descId = useId('cascivo-alert-dialog-desc')
  const isOpen = useEffectPropSignal(open)

  const cancelRef = useRef<HTMLButtonElement>(null)
  const onCancelRef = useRef(onCancel)
  onCancelRef.current = onCancel
  const onConfirmRef = useRef(onConfirm)
  onConfirmRef.current = onConfirm

  useSignalEffect(() => {
    const el = dialogRef.current
    if (!el) return
    if (isOpen.value) {
      try {
        el.showPopover()
      } catch {
        /* noop */
      }
      requestAnimationFrame(() => focusElement(cancelRef.current))
    } else {
      try {
        el.hidePopover()
      } catch {
        /* noop */
      }
    }
  })

  return (
    <div
      ref={dialogRef}
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      popover="manual"
      role="alertdialog"
      aria-modal="true"
      aria-labelledby={titleId}
      aria-describedby={descId}
      data-state={open ? 'open' : 'closed'}
      data-variant={variant}
      className={styles.dialog}
    >
      <div className={styles.content}>
        <p id={titleId} className={styles.title}>
          {title}
        </p>
        <p id={descId} className={styles.description}>
          {description}
        </p>
        <div className={styles.actions}>
          <button
            ref={cancelRef}
            type="button"
            className={styles.cancel}
            onClick={() => onCancelRef.current()}
          >
            {labels?.cancel ?? t(builtin.alertDialog.cancel)}
          </button>
          <button type="button" className={styles.confirm} onClick={() => onConfirmRef.current()}>
            {labels?.confirm ?? t(builtin.alertDialog.confirm)}
          </button>
        </div>
      </div>
    </div>
  )
}

@layer cascivo.component {
  .dialog {
    position: fixed;
    inset: 0;
    margin: auto;
    padding: 0;
    border: none;
    background: transparent;
    width: fit-content;
    height: fit-content;

    opacity: 1;
    scale: 1;
    transition:
      opacity var(--cascivo-motion-enter),
      scale var(--cascivo-motion-enter),
      display var(--cascivo-motion-enter) allow-discrete,
      overlay var(--cascivo-motion-enter) allow-discrete;

    @starting-style {
      opacity: 0;
      scale: 0.95;
    }

    &[data-state='closed'] {
      opacity: 0;
      scale: 0.95;
      transition:
        opacity var(--cascivo-motion-exit),
        scale var(--cascivo-motion-exit),
        display var(--cascivo-motion-exit) allow-discrete,
        overlay var(--cascivo-motion-exit) allow-discrete;
    }

    &::backdrop {
      background-color: rgb(0 0 0 / 0.5);
      backdrop-filter: blur(2px);
      opacity: 1;
      transition:
        opacity var(--cascivo-motion-enter),
        display var(--cascivo-motion-enter) allow-discrete,
        overlay var(--cascivo-motion-enter) allow-discrete;

      @starting-style {
        opacity: 0;
      }
    }

    &[data-state='closed']::backdrop {
      opacity: 0;
      transition:
        opacity var(--cascivo-motion-exit),
        display var(--cascivo-motion-exit) allow-discrete,
        overlay var(--cascivo-motion-exit) allow-discrete;
    }
  }

  .content {
    width: 28rem;
    max-width: calc(100vw - var(--cascivo-space-8));
    background: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-overlay);
    box-shadow: var(--cascivo-shadow-overlay);
    padding: var(--cascivo-space-6);
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-2);
  }

  .title {
    margin: 0;
    font-size: var(--cascivo-text-lg);
    font-weight: var(--cascivo-font-semibold);
    color: var(--cascivo-color-text);
  }

  .description {
    margin: 0;
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
  }

  .actions {
    display: flex;
    justify-content: flex-end;
    gap: var(--cascivo-space-2);
    margin-block-start: var(--cascivo-space-4);
  }

  /* viewport-query: the dialog is in the top layer, so no ancestor contains it and a
     @container query would match nothing. The bottom-sheet form is a property of the
     screen, not of any slot. */
  @media (max-width: 40rem) {
    .dialog {
      /* Pin to bottom viewport edge — bottom-sheet */
      margin: 0;
      inset-block-end: 0;
      inset-inline: 0;
      max-block-size: 90dvh;
    }

    .content {
      inline-size: 100%;
      max-width: 100%;
      border-end-start-radius: 0;
      border-end-end-radius: 0;
      border-start-start-radius: var(--cascivo-radius-overlay);
      border-start-end-radius: var(--cascivo-radius-overlay);
      max-block-size: 90dvh;
      overflow-y: auto;
      /* Safe area for home indicator on iOS */
      padding-block-end: env(safe-area-inset-bottom, 0);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .dialog {
      transition: none;
    }
    .dialog[data-state='closed'] {
      transition: none;
    }
  }

  .cancel,
  .confirm {
    padding: var(--cascivo-space-2) var(--cascivo-space-4);
    border-radius: var(--cascivo-radius-control);
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    cursor: pointer;
    border: 1px solid transparent;
    transition:
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      color var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }

  .cancel {
    background: var(--cascivo-color-bg-subtle);
    color: var(--cascivo-color-text);
    border-color: var(--cascivo-color-border);

    &:hover {
      background: var(--cascivo-color-bg-subtle);
    }
  }

  .confirm {
    background: var(--cascivo-color-accent);
    color: var(--cascivo-color-text-on-accent);

    &:hover {
      opacity: 0.9;
    }

    [data-variant='destructive'] & {
      background: var(--cascivo-color-destructive);
      color: var(--cascivo-color-text-on-destructive);
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'AlertDialog',
  description: 'Confirmation dialog requiring explicit user action; no light-dismiss',
  category: 'overlay',
  clientJs: 'required',
  states: ['open', 'closed'],
  variants: ['default', 'destructive'],
  sizes: [],
  props: [
    {
      name: 'open',
      description: 'Whether the component is open (controlled).',
      type: 'boolean',
      required: true,
    },
    {
      name: 'title',
      description: 'Title text for the component.',
      type: 'string',
      required: true,
    },
    {
      name: 'description',
      description: 'Supporting description text.',
      type: 'string',
      required: true,
    },
    {
      name: 'onConfirm',
      description: 'Called when the confirm button is activated.',
      type: '() => void',
      required: true,
    },
    {
      name: 'onCancel',
      description: 'Called when the cancel button is activated.',
      type: '() => void',
      required: true,
    },
    {
      name: 'labels',
      description: 'Overrides for the component’s user-visible strings (i18n).',
      type: 'AlertDialogLabels',
      required: false,
    },
    {
      name: 'variant',
      description:
        '`destructive` styles the confirm button as a danger action; `default` styles it as the primary action. Use `destructive` for anything that deletes.',
      type: "'destructive' | 'default'",
      required: false,
      default: 'default',
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-radius-lg',
    '--cascivo-shadow-xl',
    '--cascivo-motion-enter',
    '--cascivo-motion-exit',
    '--cascivo-color-accent',
    '--cascivo-color-destructive',
  ],
  accessibility: {
    role: 'alertdialog',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Shift+Tab', 'Enter', 'Space'],
  },
  examples: [
    {
      title: 'Destructive confirm',
      code: `<AlertDialog
  open={isOpen}
  variant="destructive"
  title="Delete project?"
  description="This permanently removes the project and cannot be undone."
  onConfirm={remove}
  onCancel={() => setIsOpen(false)}
/>`,
    },
    {
      title: 'Custom action labels',
      code: `<AlertDialog
  open={isOpen}
  title="Sign out?"
  description="Unsaved changes will be lost."
  labels={{ confirm: 'Sign out', cancel: 'Stay' }}
  onConfirm={signOut}
  onCancel={() => setIsOpen(false)}
/>`,
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['overlay', 'dialog', 'confirm', 'destructive'],
  intent: {
    whenToUse: [
      'Confirming a destructive or irreversible action (delete, overwrite, sign out) before it happens',
      'Interrupting a flow to force an explicit decision the user must acknowledge',
    ],
    whenNotToUse: [
      'Showing non-critical information or forms — use Modal, which supports light-dismiss and arbitrary content',
      'Confirming a low-stakes action where an undoable Toast is friendlier and less interruptive',
    ],
    antiPatterns: [
      {
        bad: 'Using AlertDialog for a multi-field form or rich content',
        good: 'Use Modal for content; reserve AlertDialog for a title + description + confirm/cancel decision',
        why: 'AlertDialog only renders a title, description, and two action buttons, and is role="alertdialog" with no light-dismiss — it is built to demand a yes/no answer, not host content',
      },
      {
        bad: 'Adding a backdrop/Escape close to dismiss the dialog without choosing',
        why: 'It uses popover="manual" so it cannot be light-dismissed by design — closing must go through onConfirm/onCancel so the decision is always explicit',
      },
    ],
    related: [
      {
        name: 'Modal',
        relationship: 'alternative',
        reason:
          'Use for general dialogs with content and light-dismiss; AlertDialog is the must-acknowledge confirm',
      },
      {
        name: 'Toast',
        relationship: 'alternative',
        reason:
          'Prefer an undoable Toast for reversible low-stakes actions instead of a blocking confirm',
      },
      {
        name: 'Button',
        relationship: 'pairs-with',
        reason: 'A Button typically triggers the action that opens the AlertDialog',
      },
    ],
    a11yRationale:
      'Uses role="alertdialog" with aria-modal and labelled/described-by wiring so assistive tech announces it as an interruptive decision; focus moves to the cancel button on open so the safe default is selected, and popover="manual" prevents accidental dismissal that would skip the decision',
    content: {
      tone: 'Direct and specific — name the exact consequence',
      notes:
        'Title states the action ("Delete project?"); description states what is lost and whether it is reversible; confirm label is the verb ("Delete"), not "OK"',
    },
    flexibility: [
      {
        area: 'dismiss behavior',
        level: 'strict',
        note: 'No light-dismiss — closing must go through onConfirm/onCancel',
      },
      {
        area: 'action labels',
        level: 'flexible',
        note: 'confirm/cancel copy overridable via labels; defaults come from the i18n catalog',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Visual styling resolves to semantic --cascivo-color-* tokens; destructive variant uses --cascivo-color-destructive',
      },
    ],
  },
}
